async function copyCanvasSelection(){
  if(!hasCanvasSelection())throw Error(t('没有可复制的选中内容','There is no selected content to copy'));
  const doc=frame.contentDocument,clipboardApi=frame.contentWindow?.navigator?.clipboard;
  const dropdown=doc?.querySelector('[data-testid="copy-button-dropdown-triangle"]');
  if(!dropdown||!clipboardApi)throw Error(t('画布复制命令当前不可用','The canvas copy command is currently unavailable'));
  const ownWriteText=Object.getOwnPropertyDescriptor(clipboardApi,'writeText');let captured='';
  try{
    Object.defineProperty(clipboardApi,'writeText',{configurable:true,value:async source=>{captured=String(source||'');}});
    dropdown.click();
    let button=null;
    for(let i=0;i<20&&!button;i++){await new Promise(resolve=>setTimeout(resolve,15));button=doc.querySelector('[data-testid="copy-ket-button"]');}
    if(!button||button.disabled)throw Error(t('画布复制命令当前不可用','The canvas copy command is currently unavailable'));
    button.click();
    for(let i=0;i<12&&!captured;i++)await new Promise(resolve=>setTimeout(resolve,20));
  }finally{
    if(ownWriteText)Object.defineProperty(clipboardApi,'writeText',ownWriteText);else delete clipboardApi.writeText;
  }
  if(!captured)throw Error(t('没有取得可编辑的复制内容','Could not obtain editable copied content'));
  await window.desktop.writeCanvasClipboard(captured);
}
let contextMenuRequest=0,pendingCanvasCopy=null;
