function stats(p){const ket=JSON.parse(p.ket),count={molecules:0,atoms:0,bonds:0,texts:0,arrows:0};for(const n of ket.root.nodes){const v=n.$ref?ket[n.$ref]:n;if(v?.type==='molecule'){count.molecules++;count.atoms+=v.atoms?.length||0;count.bonds+=v.bonds?.length||0;}else if(v?.type==='text')count.texts++;else if(v?.type==='arrow')count.arrows++;}return count;}
async function renameDoc(id,value){const d=docs.find(item=>item.id===id);if(!d)return;if(d.id===activeId)await readChanges();const next=uniqueRename(String(value||'').trim().slice(0,200)||'Untitled Drawing',id);if(next===d.name){render();return;}pushHistory(d);d.name=next;render();await persist(d);await saveMeta();toast(t('画布已重命名','Canvas renamed'));}
function beginDockRename(d,el,name){if(el.classList.contains('renaming'))return;el.classList.add('renaming');el.title='';const input=document.createElement('input');input.className='doc-tile-rename';input.value=d.name;input.maxLength=200;input.setAttribute('aria-label',t('画布名称','Canvas name'));input.onclick=input.ondblclick=event=>event.stopPropagation();name.replaceWith(input);let done=false;const finish=save=>{if(done)return;done=true;if(save)work(t('重命名画布…','Renaming canvas…'),()=>renameDoc(d.id,input.value));else renderDock();};input.onkeydown=event=>{event.stopPropagation();if(event.key==='Enter'){event.preventDefault();finish(true);}else if(event.key==='Escape'){event.preventDefault();finish(false);}};input.onblur=()=>finish(true);requestAnimationFrame(()=>{input.focus();input.select();});}
