function render(){const p=project;$('#project-name').value=p?.name||'';$('#drawing-style').value=p?.drawingStyle||'standard';$('#drawing-style').title=p&&isACS(p)?t('使用选择工具拖动原子，可手动调整键长和键角','Use the selection tool to drag atoms and adjust bond lengths and angles'):'';document.title=(p?.name||'Structlnk')+' · Structlnk';$('#style-summary').textContent=p?(isACS(p)?t('默认键长 14.4 pt · 可拖动原子疏排','Default bond 14.4 pt · drag atoms to adjust geometry'):t('结构、文字与箭头在同一画布编辑','Edit structures, text, and arrows on one canvas')):'';$('[data-export="png"]').textContent=p&&isACS(p)?t('PNG · 透明 / 600 dpi','PNG · Transparent / 600 dpi'):t('PNG · 透明 / 3×','PNG · Transparent / 3×');$('[data-export="pdf"]').textContent=p&&isACS(p)?t('PDF · US Letter / 原尺寸','PDF · US Letter / actual size'):t('PDF · A4 横向','PDF · A4 landscape');$('#original-export').classList.toggle('hidden',!p?.originalProject);$('#undo').disabled=!p?.history.length;$('#redo').disabled=!p?.future.length;if(p){const c=stats(p);$('#object-count').textContent=t(`${c.atoms} 个原子 · ${c.bonds} 条键 · ${c.texts} 处文字 · ${c.arrows} 个箭头`,`${c.atoms} atoms · ${c.bonds} bonds · ${c.texts} texts · ${c.arrows} arrows`);$('#save-state').textContent=signature(p)===p.savedSig?t('已保存','Saved'):t('自动恢复 · Ctrl+S 保存','Auto-recovered · Ctrl+S to save');}else{$('#object-count').textContent='';$('#save-state').textContent=t('没有打开的窗口 · 点击底部窗口条还原','No open window · click a tab below to restore');}$('#doc-empty').classList.toggle('hidden',!!p);renderDock();}
