async function readChanges(){readQueue=readQueue.catch(()=>{}).then(async()=>{if(suppress||!engine||!project)return;let highlights=currentHighlights(),ket=await engine.getKet(),remember=performance.now()>=programmaticUntil,normalized=normalizeMergedAromaticRings(ket);if(normalized.fixes){suppress++;try{await engine.setMolecule(normalized.ket,{preserveCanvasPosition:true});settings();ket=await engine.getKet();applyHighlights(highlights);programmaticUntil=performance.now()+500;}finally{suppress--;}toast('已自动修正连接处的碳价态并隐藏碳标记');}if(ket!==project.ket||encode(highlights)!==encode(project.highlights||[])){if(remember)pushHistory(project);project.ket=ket;project.highlights=highlights;render();}});await readQueue;}
