function canvasBounds(struct=engine?.editor?.struct()){const points=[];for(const id of ids(struct?.atoms)){const p=struct.atoms.get(id)?.pp;if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))points.push(p);}for(const id of ids(struct?.texts)){const text=struct.texts.get(id),p=text?.position||text?.pp;if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))points.push(p);}for(const id of ids(struct?.rxnArrows)){const arrow=struct.rxnArrows.get(id);for(const p of arrow?.pos||[])if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))points.push(p);}if(!points.length)return null;return {minX:Math.min(...points.map(p=>p.x)),maxX:Math.max(...points.map(p=>p.x)),minY:Math.min(...points.map(p=>p.y)),maxY:Math.max(...points.map(p=>p.y))};}
